(function(){const{commands=[]}=window.GroundhoggCommands;const store=wp.data.dispatch("core/commands");const actions={set_admin_theme:async({theme,nonce,stylesheet})=>{const response=await fetch(window.ajaxurl,{method:"POST",credentials:"same-origin",body:new URLSearchParams({action:"gh_set_admin_theme",_wpnonce:nonce,theme:theme})});const{success}=await response.json();if(!success){return}if(!document.body.classList.contains("groundhogg-admin-page")){return}if(!document.getElementById("groundhogg-admin-themes-css")){const link=document.createElement("link");link.id="groundhogg-admin-themes-css";link.rel="stylesheet";link.href=stylesheet;document.head.appendChild(link)}document.body.classList.remove(...[...document.body.classList].filter(c=>c.startsWith("gh-theme-")));if(theme!=="default"){document.body.classList.add(`gh-theme-${theme}`)}}};window.GroundhoggCommands.actions=actions;commands.forEach(({name,label,url,action,args,category,keywords})=>store.registerCommand({name:name,label:label,searchLabel:label,category:category,keywords:keywords,callback:({close})=>{close();if(url){window.location.href=url;return}if(actions.hasOwnProperty(action)){actions[action](args)}}}))})();